#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    long long p;
    long long s;
    cin >> n >> m >> p >> s;
    vector<long long> tasks(n);
    for (int i = 0; i < n; i++) cin >> tasks[i];
    vector<long long> workers(m);
    for (int i = 0; i < m; i++) cin >> workers[i];

    sort(tasks.begin(), tasks.end());
    sort(workers.begin(), workers.end());
    long long lo = 0, hi = min(n, m);
    vector<long long> dq(n + 1);
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        long long pills = p;
        long long head = 0, tail = 0, ptr = 0;
        bool ok = true;
        for (long long wi = m - mid; wi < m; wi++) {
            long long w = workers[wi];
            while (ptr < mid && tasks[ptr] <= w + s) dq[tail++] = tasks[ptr++];
            if (head == tail) {
                ok = false;
                break;
            }
            if (dq[head] <= w) {
                head++;
            } else {
                if (pills == 0) {
                    ok = false;
                    break;
                }
                pills--;
                tail--;
            }
        }
        if (ok) lo = mid;
        else hi = mid - 1;
    }
    cout << lo << "\n";

    return 0;
}

