import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long p = Long.parseLong(next());
        long s = Long.parseLong(next());
        long[] tasks = new long[(int) n];
        for (int i = 0; i < tasks.length; i++) tasks[i] = Long.parseLong(next());
        long[] workers = new long[(int) m];
        for (int i = 0; i < workers.length; i++) workers[i] = Long.parseLong(next());

        Arrays.sort(tasks);
        Arrays.sort(workers);
        int nt = (int) n, nw = (int) m;
        int lo = 0, hi = Math.min(nt, nw);
        long[] dq = new long[nt + 1];
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            long pills = p;
            int head = 0, tail = 0, ptr = 0;
            boolean ok = true;
            for (int wi = nw - mid; wi < nw; wi++) {
                long w = workers[wi];
                while (ptr < mid && tasks[ptr] <= w + s) {
                    dq[tail++] = tasks[ptr];
                    ptr++;
                }
                if (head == tail) {
                    ok = false;
                    break;
                }
                if (dq[head] <= w) {
                    head++;
                } else {
                    if (pills == 0) {
                        ok = false;
                        break;
                    }
                    pills--;
                    tail--;
                }
            }
            if (ok) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }
}
